// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    address constant VICTIM = address(0xA11CE);
    uint256 constant D = 1 ether;
    uint256 constant V = 3 ether;

    function setUp() public {
        c = new Wallet();
        vm.deal(VICTIM, V);
        vm.prank(VICTIM);
        c.deposit{value: V}();
    }

    function _attack(address caller) internal {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        vm.assume(caller != VICTIM);
        vm.assume(uint160(caller) > 0xffff);
        vm.assume(caller.code.length == 0);

        vm.deal(caller, D);
        vm.prank(caller);
        c.deposit{value: D}();

        vm.prank(caller);
        c.refund();
        vm.prank(caller);
        c.refund();

        assertLe(caller.balance, D);
    }

    function testFuzz_property(address caller) public {
        _attack(caller);
    }
}
